94d\u0925\u093f\u0924\u093f \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0939\u094b \u0938\u0915\u0947\u0964", "\u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u093e\u0928\u0915 \u092c\u0939\u0941\u091a\u0930 \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u092e\u093e\u0928\u0915\u094b\u0902 (lookback 96, horizons 96/192/336/720) \u0915\u093e \u092a\u093e\u0932\u0928 \u0915\u0930\u0924\u093e \u0939\u0948\u0964"], "stage": "result", "summary": "CycleNet \u092e\u0949\u0921\u0932 \u0915\u0947 \u0915\u093e\u0930\u094d\u092f\u093e\u0928\u094d\u0935\u092f\u0928 \u0914\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0939\u0947\u0924\u0941 \u0935\u093f\u0938\u094d\u0924\u0943\u0924, \u0924\u0930\u094d\u0915\u0938\u0902\u0917\u0924 \u0914\u0930 \u092c\u0939\u0941-\u0906\u0935\u0927\u093f\u0915 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e\u0964", "answer": "# \u0906\u0935\u0927\u093f\u0915 \u092a\u0948\u091f\u0930\u094d\u0928 \u0935\u093e\u0932\u0947 \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0921\u0947\u091f\u093e \u0915\u0947 \u0932\u093f\u090f CycleNet \u092e\u0949\u0921\u0932 \u0915\u093e \u092a\u0942\u0930\u094d\u0923 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 (Full Experiment Design)\n\n---\n\n## 1. \u0938\u093e\u0930\u093e\u0902\u0936 \u090f\u0935\u0902 \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f (Executive Summary & Objectives)\n\u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0921\u0947\u091f\u093e (\u0935\u093f\u0936\u0947\u0937\u0915\u0930 \u092c\u093f\u091c\u0932\u0940 \u0917\u094d\u0930\u093f\u0921 \u0916\u092a\u0924 \u0914\u0930 \u091f\u094d\u0930\u0948\u092b\u093c\u093f\u0915 \u092a\u094d\u0930\u0935\u093e\u0939) \u092e\u0947\u0902 \u0938\u094d\u0935\u093e\u092d\u093e\u0935\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0936\u0915\u094d\u0924\u093f\u0936\u093e\u0932\u0940 \u0906\u0935\u0927\u093f\u0915 (periodic/seasonal) \u092a\u0948\u091f\u0930\u094d\u0928 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u2014\u091c\u0948\u0938\u0947 24 \u0918\u0902\u091f\u0947 \u0915\u093e \u0926\u0948\u0928\u093f\u0915 \u091a\u0915\u094d\u0930 ($S_1 = 24$) \u0914\u0930 7 \u0926\u093f\u0928 (168 \u0918\u0902\u091f\u0947) \u0915\u093e \u0938\u093e\u092a\u094d\u0924\u093e\u0939\u093f\u0915 \u091a\u0915\u094d\u0930 ($S_2 = 168$)\u0964 \n\n\u0907\u0938 \u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u093e \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f **CycleNet** (\u090f\u0915 \u0932\u0940\u0928\u093f\u092f\u0930/\u0905\u0935\u0936\u093f\u0937\u094d\u091f \u0906\u0927\u093e\u0930\u093f\u0924 \u091a\u0915\u094d\u0930\u0940\u092f \u092e\u0949\u0921\u0932\u093f\u0902\u0917 \u0928\u0947\u091f\u0935\u0930\u094d\u0915) \u0915\u094b \u0932\u093e\u0917\u0942 \u0914\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 \u0915\u0930\u0928\u0947 \u0939\u0947\u0924\u0941 \u090f\u0915 \u092a\u0942\u0930\u094d\u0923, \u092a\u0941\u0928\u0930\u0941\u0924\u094d\u092a\u093e\u0926\u0915 \u0914\u0930 \u0915\u0920\u094b\u0930 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u0930\u0928\u093e \u0939\u0948\u0964 CycleNet \u091c\u091f\u093f\u0932 \u0914\u0930 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0930\u0942\u092a \u0938\u0947 \u092d\u093e\u0930\u0940 \u0927\u094d\u092f\u093e\u0928 \u0924\u0902\u0924\u094d\u0930 (self-attention) \u0915\u0947 \u0938\u094d\u0925\u093e\u0928 \u092a\u0930 \u0939\u0932\u094d\u0915\u0947, \u0938\u0940\u0916\u0928\u0947 \u092f\u094b\u0917\u094d\u092f \u0906\u0935\u0927\u093f\u0915 \u091a\u0915\u094d\u0930 \u092e\u093e\u092a\u0926\u0902\u0921\u094b\u0902 (learnable cyclical parameters) \u0914\u0930 \u0905\u0935\u0936\u093f\u0937\u094d\u091f \u0938\u0902\u0930\u091a\u0928\u093e (residual structure) \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 2. \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0906\u0927\u093e\u0930 \u0914\u0930 \u092e\u0949\u0921\u0932 \u0917\u0923\u093f\u0924\u0940\u092f \u0938\u0942\u0924\u094d\u0930\u0940\u0915\u0930\u0923 (Theoretical Formulation of CycleNet)\n\nCycleNet \u0915\u093e \u092e\u0942\u0932 \u0935\u093f\u091a\u093e\u0930 \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u094b \u0909\u0938\u0915\u0947 \u0905\u0902\u0924\u0930\u094d\u0928\u093f\u0939\u093f\u0924 \u091a\u0915\u094d\u0930\u0940\u092f \u091a\u0930\u0923\u094b\u0902 (cyclic phases) \u0914\u0930 \u0905\u0935\u0936\u093f\u0937\u094d\u091f \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f\u092f\u094b\u0902 (residual trends) \u092e\u0947\u0902 \u0935\u093f\u0918\u091f\u093f\u0924 \u0915\u0930\u0928\u093e \u0939\u0948\u0964\n\n### 2.1 \u0907\u0928\u092a\u0941\u091f \u0914\u0930 \u0938\u093e\u092e\u093e\u0928\u094d\u092f\u0940\u0915\u0930\u0923 (Reversible Instance Normalization - RevIN)\n\u0917\u0948\u0930-\u0938\u094d\u0925\u093f\u0930\u0924\u093e (non-stationarity) \u0914\u0930 \u0935\u093f\u0924\u0930\u0923 \u0935\u093f\u091a\u0932\u0928 (distribution shift) \u0915\u094b \u0939\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f:\n1. \u0907\u0928\u092a\u0941\u091f \u0935\u093f\u0902\u0921\u094b: $\\mathbf{X} \\in \\mathbb{R}^{L \\times C}$, \u091c\u0939\u093e\u0901 $L$ \u0932\u0941\u0915\u092c\u0948\u0915 \u0932\u0902\u092c\u093e\u0908 \u0939\u0948 \u0914\u0930 $C$ \u0935\u0948\u0930\u093f\u090f\u092c\u0932\u094d\u0938 \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0939\u0948\u0964\n2. \u092a\u094d\u0930\u0924\u093f-\u0928\u092e\u0942\u0928\u093e \u0914\u0938\u0924 $\\mu_{\\mathbf{X}}$ \u0914\u0930 \u092e\u093e\u0928\u0915 \u0935\u093f\u091a\u0932\u0928 $\\sigma_{\\mathbf{X}}$ \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u093e\u092e\u093e\u0928\u094d\u092f\u0940\u0915\u0930\u0923:\n   $$\\tilde{\\mathbf{X}} = \\frac{\\mathbf{X} - \\mu_{\\mathbf{X}}}{\\sigma_{\\mathbf{X}} + \\epsilon}$$\n\n### 2.2 \u091a\u0915\u094d\u0930\u0940\u092f \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 (Cyclic Representation & Multi-Periodicity)\n- **\u090f\u0915\u0932 \u0906\u0935\u0927\u093f\u0915\u0924\u093e (Single Period):** \u0926\u0948\u0928\u093f\u0915 \u091a\u0915\u094d\u0930 \u0915\u0947 \u0932\u093f\u090f \u0905\u0935\u0927\u093f $S_1 = 24$\u0964 \u0938\u092e\u092f \u092c\u093f\u0902\u0926\u0941 $t$ \u092a\u0930 \u091a\u0915\u094d\u0930\u0940\u092f \u091a\u0930\u0923 $p_1(t) = t \\pmod{S_1}$ \u0926\u094d\u0935\u093e\u0930\u093e \u0905\u0928\u0941\u0915\u094d\u0930\u092e\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n- **\u092c\u0939\u0941-\u0906\u0935\u0927\u093f\u0915\u0924\u093e (Multi-Periodicity Integration):** \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0926\u0941\u0928\u093f\u092f\u093e \u0915\u0947 \u0921\u0947\u091f\u093e \u092e\u0947\u0902 \u0926\u0948\u0928\u093f\u0915 \u0914\u0930 \u0938\u093e\u092a\u094d\u0924\u093e\u0939\u093f\u0915 \u0926\u094b\u0928\u094b\u0902 \u0906\u0935\u0927\u093f\u0915\u0924\u093e\u090f\u0902 \u0938\u092e\u093e\u0928\u093e\u0902\u0924\u0930 \u0939\u094b\u0924\u0940 \u0939\u0948\u0902:\n  $$p_1(t) = t \\pmod{24}, \\quad p_2(t) = t \\pmod{168}$$\n  \u0938\u0940\u0916\u0928\u0947 \u092f\u094b\u0917\u094d\u092f \u0906\u0935\u0927\u093f\u0915 \u0935\u091c\u0928 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938:\n  $$\\mathbf{W}_{\\text{cycle}, 1} \\in \\mathbb{R}^{S_1 \\times D}, \\quad \\mathbf{W}_{\\text{cycle}, 2} \\in \\mathbb{R}^{S_2 \\times D}$$\n  \u091a\u0915\u094d\u0930\u0940\u092f \u092b\u0940\u091a\u0930 $\\mathbf{C}(t)$ \u0926\u094b\u0928\u094b\u0902 \u091a\u0915\u094d\u0930\u094b\u0902 \u0915\u093e \u0938\u0902\u092f\u0941\u0915\u094d\u0924 \u092f\u094b\u0917 \u0939\u094b\u0924\u093e \u0939\u0948:\n  $$\\mathbf{C}(t) = \\text{Embedding}_1(p_1(t)) + \\text{Embedding}_2(p_2(t))$$\n\n### 2.3 \u0905\u0935\u0936\u093f\u0937\u094d\u091f \u0938\u0902\u0930\u091a\u0928\u093e \u0914\u0930 \u092a\u0942\u0930\u094d\u0935\u093e\u0928\u0941\u092e\u093e\u0928 \u092e\u0948\u092a\u093f\u0902\u0917 (Residual Forecasting Block)\nCycleNet \u092a\u0942\u0930\u094d\u0935\u093e\u0928\u0941\u092e\u093e\u0928 \u0915\u094b \u0926\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0936\u093e\u0916\u093e\u0913\u0902 \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948:\n1. **\u091a\u0915\u094d\u0930\u0940\u092f \u0918\u091f\u0915 ($\\hat{\\mathbf{Y}}_{\\text{cycle}}$):**\n   \u092d\u0935\u093f\u0937\u094d\u092f \u0915\u0947 $H$ \u0938\u092e\u092f \u091a\u0930\u0923\u094b\u0902 ($t+1, \\dots, t+H$) \u0915\u0947 \u0932\u093f\u090f \u091c\u094d\u091e\u093e\u0924 \u091a\u0915\u094d\u0930\u0940\u092f \u091a\u0930\u0923\u094b\u0902 \u0915\u094b \u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u091f \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948:\n   $$\\hat{\\mathbf{Y}}_{\\text{cycle}} = \\text{Linear}_{\\text{cycle}}(\\mathbf{C}(t+1 : t+H))$$\n2. **\u0905\u0935\u0936\u093f\u0937\u094d\u091f / \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f \u0918\u091f\u0915 ($\\hat{\\mathbf{Y}}_{\\text{residual}}$):**\n   \u0932\u0941\u0915\u092c\u0948\u0915 \u0921\u0947\u091f\u093e \u0938\u0947 \u0917\u0948\u0930-\u0906\u0935\u0927\u093f\u0915 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0914\u0930 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0930\u0941\u091d\u093e\u0928\u094b\u0902 \u0915\u094b \u0915\u0948\u092a\u094d\u091a\u0930 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0938\u0940\u0927\u093e \u0932\u0940\u0928\u093f\u092f\u0930 \u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u0936\u0928:\n   $$\\hat{\\mathbf{Y}}_{\\text{residual}} = \\text{Linear}_{\\text{res}}(\\tilde{\\mathbf{X}})$$\n3. **\u0938\u0902\u092f\u0941\u0915\u094d\u0924 \u0906\u0909\u091f\u092a\u0941\u091f \u090f\u0935\u0902 \u0921\u0940-\u0928\u0949\u0930\u094d\u092e\u0932\u093e\u0907\u091c\u0947\u0936\u0928:**\n   $$\\hat{\\tilde{\\mathbf{Y}}} = \\hat{\\mathbf{Y}}_{\\text{cycle}} + \\hat{\\mathbf{Y}}_{\\text{residual}}$$\n   $$\\hat{\\mathbf{Y}} = \\hat{\\tilde{\\mathbf{Y}}} \\cdot (\\sigma_{\\mathbf{X}} + \\epsilon) + \\mu_{\\mathbf{X}}$$\n\n---\n\n## 3. \u0921\u0947\u091f\u093e \u092a\u093e\u0907\u092a\u0932\u093e\u0907\u0928 \u0914\u0930 \u092a\u094d\u0930\u0940\u092a\u094d\u0930\u094b\u0938\u0947\u0938\u093f\u0902\u0917 (Data Pipeline & Preprocessing)\n\n### 3.1 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u0921\u0947\u091f\u093e\u0938\u0947\u091f\u094d\u0938\n1. **Electricity (ECL):**\n   - \u0935\u093f\u0935\u0930\u0923: 321 \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902 \u0915\u0940 \u092a\u094d\u0930\u0924\u093f \u0918\u0902\u091f\u093e \u092c\u093f\u091c\u0932\u0940 \u0916\u092a\u0924\u0964\n   - \u0935\u093f\u0936\u0947\u0937\u0924\u093e\u090f\u0902: \u0938\u094d\u092a\u0937\u094d\u091f 24-\u0918\u0902\u091f\u0947 (\u0926\u0948\u0928\u093f\u0915) \u0914\u0930 168-\u0918\u0902\u091f\u0947 (\u0938\u093e\u092a\u094d\u0924\u093e\u0939\u093f\u0915) \u092a\u0948\u091f\u0930\u094d\u0928\u0964\n2. **Traffic:**\n   - \u0935\u093f\u0935\u0930\u0923: \u0938\u0948\u0928 \u092b\u094d\u0930\u093e\u0902\u0938\u093f\u0938\u094d\u0915\u094b \u092c\u0947 \u090f\u0930\u093f\u092f\u093e \u092b\u094d\u0930\u0940\u0935\u0947 \u092a\u0930 862 \u0938\u0947\u0902\u0938\u0930\u094b\u0902 \u0926\u094d\u0935\u093e\u0930\u093e \u092e\u093e\u092a\u0940 \u0917\u0908 \u0938\u0921\u093c\u0915 \u0905\u0927\u093f\u092d\u094b\u0917 \u0926\u0930 (Road occupancy rate - hourly)\u0964\n   - \u0935\u093f\u0936\u0947\u0937\u0924\u093e\u090f\u0902: \u092e\u091c\u092c\u0942\u0924 \u0926\u0948\u0928\u093f\u0915 \u0935\u094d\u092f\u0938\u094d\u0924 \u0938\u092e\u092f (peak hours) \u0914\u0930 \u0915\u093e\u0930\u094d\u092f\u0926\u093f\u0935\u0938 \u092c\u0928\u093e\u092e \u0938\u092a\u094d\u0924\u093e\u0939\u093e\u0902\u0924 \u0906\u0935\u0927\u093f\u0915\u0924\u093e\u0964\n\n### 3.2 \u0921\u0947\u091f\u093e \u0935\u093f\u092d\u093e\u091c\u0928 \u0914\u0930 \u0935\u093f\u0902\u0921\u094b\u0907\u0902\u0917 (Splitting & Windowing)\n- **\u0935\u093f\u092d\u093e\u091c\u0928 \u0905\u0928\u0941\u092a\u093e\u0924:** \u0915\u093e\u0932\u093e\u0928\u0941\u0915\u094d\u0930\u092e\u093f\u0915 (Chronological) \u0935\u093f\u092d\u093e\u091c\u0928: 70% \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917, 10% \u0935\u0948\u0932\u093f\u0921\u0947\u0936\u0928, 20% \u091f\u0947\u0938\u094d\u091f\u093f\u0902\u0917\u0964 (\u0921\u0947\u091f\u093e \u0932\u0940\u0915\u0947\u091c \u0930\u094b\u0915\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0936\u092b\u0932\u093f\u0902\u0917 \u0928\u0939\u0940\u0902 \u0915\u0940 \u091c\u093e\u090f\u0917\u0940)\u0964\n- **\u0932\u0941\u0915\u092c\u0948\u0915 \u0935\u093f\u0902\u0921\u094b ($L$):** $L = 96$ \u0938\u094d\u091f\u0947\u092a\u094d\u0938 (\u0905\u0917\u094d\u0930\u093f\u092e \u092a\u094d\u0930\u092f\u094b\u0917\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f $L = 336$ \u092d\u0940 \u0938\u092e\u0930\u094d\u0925\u093f\u0924)\u0964\n- **\u092a\u0942\u0930\u094d\u0935\u093e\u0928\u0941\u092e\u093e\u0928 \u0939\u094b\u0930\u093e\u0907\u091c\u0928 ($H$):** \u091a\u093e\u0930 \u092e\u093e\u0928\u0915 \u0915\u094d\u0937\u093f\u0924\u093f\u091c: $H \\in \\{96, 192, 336, 720\\}$\u0964\n- **\u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0948\u092e\u094d\u092a \u090f\u0928\u0915\u094b\u0921\u093f\u0902\u0917:** \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u091f\u093e\u0907\u092e\u0938\u094d\u091f\u0947\u092a \u0915\u0947 \u0932\u093f\u090f `hour_of_day` ($0$ \u0938\u0947 $23$) \u0914\u0930 `day_of_week` ($0$ \u0938\u0947 $6$) \u0915\u094b \u091a\u0915\u094d\u0930 \u0905\u0928\u0941\u0915\u094d\u0930\u092e\u0923\u093f\u0915\u093e (cycle index) \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0928\u093f\u0915\u093e\u0932\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n## 4. \u092e\u0949\u0921\u0932 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 \u090f\u0935\u0902 \u0915\u093e\u0930\u094d\u092f\u093e\u0928\u094d\u0935\u092f\u0928 \u0935\u093f\u0935\u0930\u0923 (Implementation Blueprint)\n\n### 4.1 PyTorch \u0938\u0902\u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u0915\u094b\u0921 \u092c\u094d\u0932\u0942\u092a\u094d\u0930\u093f\u0902\u091f\n```python\nimport torch\nimport torch.nn as nn\n\nclass RevIN(nn.Module):\n    \"\"\"Reversible Instance Normalization to eliminate distribution shifts.\"\"\"\n    def __init__(self, num_features: int, eps: float = 1e-5):\n        super().__init__()\n        self.eps = eps\n        self.affine_weight = nn.Parameter(torch.ones(num_features))\n        self.affine_bias = nn.Parameter(torch.zeros(num_features))\n\n    def forward(self, x, mode: str):\n        if mode == 'norm':\n            self.mean = torch.mean(x, dim=1, keepdim=True).detach()\n            self.stdev = torch.sqrt(torch.var(x, dim=1, keepdim=True, unbiased=False) + self.eps).detach()\n            x = (x - self.mean) / self.stdev\n            return x * self.affine_weight + self.affine_bias\n        elif mode == 'denorm':\n            x = (x - self.affine_bias) / (self.affine_weight + self.eps)\n            return x * self.stdev + self.mean\n\nclass CycleNet(nn.Module):\n    def __init__(self, seq_len: int, pred_len: int, enc_in: int, \n                 cycle_len_daily: int = 24, cycle_len_weekly: int = 168):\n        super().__init__()\n        self.seq_len = seq_len\n        self.pred_len = pred_len\n        self.revin = RevIN(enc_in)\n        \n        # 1. Residual / Trend projection (Direct Linear along temporal dimension)\n        self.linear_trend = nn.Linear(seq_len, pred_len)\n        \n        # 2. Learnable Periodic Embeddings\n        self.daily_embed = nn.Embedding(cycle_len_daily, enc_in)\n        self.weekly_embed = nn.Embedding(cycle_len_weekly, enc_in)\n        \n        # 3. Cycle projection to prediction horizon\n        self.cycle_projection = nn.Linear(enc_in, enc_in)\n        self.dropout = nn.Dropout(p=0.1)\n\n    def forward(self, x, future_daily_idx, future_weekly_idx):\n        # x: [Batch, seq_len, enc_in]\n        # future_*_idx: [Batch, pred_len]\n        \n        # RevIN normalization\n        x_norm = self.revin(x, mode='norm')\n        \n        # Residual Trend Branch: [Batch, enc_in, seq_len] -> [Batch, enc_in, pred_len]\n        trend_out = self.linear_trend(x_norm.transpose(1, 2)).transpose(1, 2)\n        \n        # Multi-Period Cycle Branch\n        c_daily = self.daily_embed(future_daily_idx)    # [Batch, pred_len, enc_in]\n        c_weekly = self.weekly_embed(future_weekly_idx)  # [Batch, pred_len, enc_in]\n        c_combined = self.dropout(c_daily + c_weekly)\n        cycle_out = self.cycle_projection(c_combined)\n        \n        # Merge residual trend + cycle\n        pred_norm = trend_out + cycle_out\n        \n        # Denormalization\n        output = self.revin(pred_norm, mode='denorm')\n        return output\n```\n\n### 4.2 \u0939\u093e\u0907\u092a\u0930\u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930 \u0935\u093f\u0928\u093f\u0930\u094d\u0926\u0947\u0936 (Hyperparameters)\n- **\u0932\u0930\u094d\u0928\u093f\u0902\u0917 \u0930\u0947\u091f (LR):** $1 \\times 10^{-3}$ (Cosine Annealing Scheduler, \u0928\u094d\u092f\u0942\u0928\u0924\u092e $1 \\times 10^{-5}$)\u0964\n- **\u092c\u0948\u091a \u0938\u093e\u0907\u091c\u093c (Batch Size):** Electricity \u0915\u0947 \u0932\u093f\u090f 32, Traffic \u0915\u0947 \u0932\u093f\u090f 16 (\u092e\u0947\u092e\u094b\u0930\u0940 \u0938\u0902\u0924\u0941\u0932\u0928 \u0939\u0947\u0924\u0941)\u0964\n- **\u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0930:** AdamW (Weight Decay: $1 \\times 10^{-4}$, $\\beta_1 = 0.9, \\beta_2 = 0.999$)\u0964\n- **\u0905\u0927\u093f\u0915\u0924\u092e \u090f\u092a\u094b\u0915\u094d\u0938 (Max Epochs):** 50\u0964\n- **\u0905\u0930\u094d\u0932\u0940 \u0938\u094d\u091f\u0949\u092a\u093f\u0902\u0917:** \u092a\u0948\u0936\u0947\u0902\u0938 (patience) = 10 \u090f\u092a\u094b\u0915\u094d\u0938 (\u0935\u0948\u0932\u093f\u0921\u0947\u0936\u0928 \u0932\u0949\u0938 \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924)\u0964\n\n---\n\n## 5. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 (Experimental Controls & Baselines)\n\n### 5.1 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 (Comparative SOTA Baselines)\n1. **DLinear:** \u092e\u093e\u0928\u0915 \u0932\u0940\u0928\u093f\u092f\u0930 \u0921\u0940\u0915\u0902\u092a\u094b\u091c\u093f\u0936\u0928 \u092e\u0949\u0921\u0932 (\u091f\u094d\u0930\u0947\u0902\u0921 \u0914\u0930 \u0938\u0940\u091c\u093c\u0928\u0932 \u0932\u0940\u0928\u093f\u092f\u0930 \u0932\u0947\u092f\u0930\u094d\u0938)\u0964\n2. **PatchTST:** \u0905\u0924\u094d\u092f\u093e\u0927\u0941\u0928\u093f\u0915 \u091a\u0948\u0928\u0932-\u0907\u0902\u0921\u093f\u092a\u0947\u0902\u0921\u0947\u0902\u091f \u092a\u0948\u091a-\u0906\u0927\u093e\u0930\u093f\u0924 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e\u0930\u0964\n3. **TimesNet:** 2D-\u0935\u0947\u0930\u093f\u090f\u0936\u0928 \u0914\u0930 \u092b\u093e\u0938\u094d\u091f \u092b\u0942\u0930\u093f\u092f\u0930 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e (FFT) \u0906\u0927\u093e\u0930\u093f\u0924 \u0906\u0935\u0927\u093f\u0915 \u0938\u0940\u090f\u0928\u090f\u0928 \u092e\u0949\u0921\u0932\u0964\n4. **N-BEATS:** \u0921\u0940\u092a \u0928\u094d\u092f\u0942\u0930\u0932 \u092c\u0947\u0938\u093f\u0938 \u090f\u0915\u094d\u0938\u092a\u0947\u0902\u0936\u0928 \u092e\u0949\u0921\u0932\u0964\n\n### 5.2 \u090f\u092c\u094d\u0932\u0947\u0936\u0928 \u0938\u094d\u091f\u0921\u0940\u091c (Ablation Controls)\n1. **\u0935\u0948\u0930\u093f\u090f\u0902\u091f A (No Cycle - Pure Linear):** \u091a\u0915\u094d\u0930\u0940\u092f \u0936\u093e\u0916\u093e \u0915\u094b \u0936\u0942\u0928\u094d\u092f \u0915\u0930 \u0926\u0947\u0928\u093e ($\\hat{\\mathbf{Y}} = \\hat{\\mathbf{Y}}_{\\text{residual}}$)\u0964\n2. **\u0935\u0948\u0930\u093f\u090f\u0902\u091f B (Single Period Only):** \u0915\u0947\u0935\u0932 \u0926\u0948\u0928\u093f\u0915 \u0906\u0935\u0927\u093f\u0915\u0924\u093e ($S_1=24$) \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n3. **\u0935\u0948\u0930\u093f\u090f\u0902\u091f C (Full Multi-Period):** \u0926\u0948\u0928\u093f\u0915 ($S=24$) + \u0938\u093e\u092a\u094d\u0924\u093e\u0939\u093f\u0915 ($S=168$) \u0915\u093e \u092a\u0942\u0930\u094d\u0923 \u092e\u0949\u0921\u0932\u0964\n4. **\u0935\u0948\u0930\u093f\u090f\u0902\u091f D (Fixed vs. Learnable Cycles):** \u092b\u093f\u0915\u094d\u0938\u094d\u0921 \u0938\u093f\u0928\u0941\u0938\u094b\u0907\u0921\u0932 (Sin/Cos) \u0906\u0935\u0927\u093f\u0915\u0924\u093e \u092c\u0928\u093e\u092e \u0932\u0930\u094d\u0928 \u0915\u0930\u0928\u0947 \u092f\u094b\u0917\u094d\u092f CycleNet \u090f\u092e\u094d\u092c\u0947\u0921\u093f\u0902\u0917\u094d\u0938 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e\u0964\n\n---\n\n## 6. \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0914\u0930 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Evaluation & Analysis Plan)\n\n### 6.1 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938\n- **Mean Squared Error (MSE):**\n  $$\\text{MSE} = \\frac{1}{H \\cdot C} \\sum_{\\tau=1}^H \\sum_{i=1}^C (Y_{\\tau, i} - \\hat{Y}_{\\tau, i})^2$$\n- **Mean Absolute Error (MAE):**\n  $$\\text{MAE} = \\frac{1}{H \\cdot C} \\sum_{\\tau=1}^H \\sum_{i=1}^C |Y_{\\tau, i} - \\hat{Y}_{\\tau, i}|$$\n\n### 6.2 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0915\u0920\u094b\u0930\u0924\u093e (Statistical Rigor)\n- \u0938\u092d\u0940 \u092a\u094d\u0930\u092f\u094b\u0917 5 \u0905\u0932\u0917-\u0905\u0932\u0917 \u0930\u0948\u0902\u0921\u092e \u0938\u0940\u0921\u094d\u0938 (`seeds = [42, 2024, 2025, 2026, 3407]`) \u0915\u0947 \u0938\u093e\u0925 \u091a\u0932\u093e\u090f \u091c\u093e\u090f\u0902\u0917\u0947\u0964\n- \u092a\u0930\u093f\u0923\u093e\u092e\u094b\u0902 \u0915\u094b **\u092e\u0940\u0928 $\\pm$ \u092e\u093e\u0928\u0915 \u0935\u093f\u091a\u0932\u0928 (Mean $\\pm$ Std)** \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0930\u093f\u092a\u094b\u0930\u094d\u091f \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n- CycleNet \u0914\u0930 \u0938\u0930\u094d\u0935\u0936\u094d\u0930\u0947\u0937\u094d\u0920 \u092c\u0947\u0938\u0932\u093e\u0907\u0928 (\u091c\u0948\u0938\u0947 PatchTST / DLinear) \u0915\u0947 \u092c\u0940\u091a \u0905\u0902\u0924\u0930 \u0915\u0940 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0947 \u0932\u093f\u090f \u092a\u0947\u092f\u0930\u094d\u0921 \u091f\u0940-\u091f\u0947\u0938\u094d\u091f (Paired t-test, $p < 0.05$) \u0914\u0930 \u0935\u093f\u0932\u0915\u0949\u0915\u094d\u0938\u0928 \u0938\u093e\u0907\u0928\u094d\u0921-\u0930\u0948\u0902\u0915 \u091f\u0947\u0938\u094d\u091f \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n### 6.3 \u0917\u0941\u0923\u093e\u0924\u094d\u092e\u0915 \u090f\u0935\u0902 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923\u093e\u0924\u094d\u092e\u0915 \u091c\u093e\u0902\u091a (Qualitative Analysis)\n1. **\u092b\u0947\u091c\u093c-\u0905\u0932\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0935\u093f\u091c\u093c\u0941\u0905\u0932\u093e\u0907\u091c\u093c\u0947\u0936\u0928:** 24-\u0918\u0902\u091f\u0947 \u0915\u0947 \u0926\u093f\u0928 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0921\u0947\u091f\u093e \u0914\u0930 CycleNet \u0915\u0947 \u091a\u0915\u094d\u0930\u0940\u092f \u0918\u091f\u0915 \u0915\u0947 \u0938\u0902\u0930\u0947\u0916\u0923 \u0915\u093e \u092a\u094d\u0932\u0949\u091f\u0964\n2. **\u0932\u0902\u092c\u0940 \u0905\u0935\u0927\u093f \u0915\u093e \u0917\u093f\u0930\u093e\u0935\u091f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923:** \u091c\u0948\u0938\u0947-\u091c\u0948\u0938\u0947 \u0939\u094b\u0930\u093e\u0907\u091c\u0928 $96 \\to 720$ \u092c\u0922\u093c\u0924\u093e \u0939\u0948, MSE \u0924\u094d\u0930\u0941\u091f\u093f \u0935\u0943\u0926\u094d\u0927\u093f \u0915\u0940 \u0926\u0930 \u0915\u093e \u092c\u0947\u0938\u0932\u093e\u0907\u0928\u094d\u0938 \u0915\u0947 \u0938\u093e\u0925 \u0924\u0941\u0932\u0928\u093e\u0924\u094d\u092e\u0915 \u0905\u0927\u094d\u092f\u092f\u0928\u0964\n\n---\n\n## 7. \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915\u0924\u093e \u0914\u0930 \u0938\u0902\u0938\u093e\u0927\u0928 \u0906\u0915\u0932\u0928 (Feasibility & Compute Assessment)\n- **\u091c\u091f\u093f\u0932\u0924\u093e (Time & Memory Complexity):** \n  CycleNet \u0915\u0940 \u0915\u092e\u094d\u092a\u094d\u092f\u0942\u091f\u0947\u0936\u0928\u0932 \u091c\u091f\u093f\u0932\u0924\u093e \u0938\u092e\u092f \u0906\u092f\u093e\u092e \u092e\u0947\u0902 $O(L + H)$ \u0939\u0948, \u091c\u094b \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e\u0930-\u0906\u0927\u093e\u0930\u093f\u0924 \u092e\u0949\u0921\u0932\u094b\u0902 \u0915\u0940 $O(L^2)$ \u091c\u091f\u093f\u0932\u0924\u093e \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 \u0905\u0924\u094d\u092f\u0902\u0924 \u0939\u0932\u094d\u0915\u0940 \u0914\u0930 \u0924\u0947\u091c\u093c \u0939\u0948\u0964\n- **\u0938\u0902\u0938\u093e\u0927\u0928 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e:** \n  - \u090f\u0915 \u092e\u093e\u0928\u0915 16GB GPU (\u0909\u0926\u093e. NVIDIA T4 / V100 / A10) \u092a\u0930 Electricity \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u093e \u090f\u0915 \u092f\u0941\u0917 (epoch) \u0932\u0917\u092d\u0917 10-15 \u0938\u0947\u0915\u0902\u0921 \u092e\u0947\u0902 \u092a\u0942\u0930\u093e \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n  - CPU \u0935\u093e\u0924\u093e\u0935\u0930\u0923 (\u0909\u0926\u093e. 24 vCPUs) \u092a\u0930 \u092d\u0940 \u092f\u0939 \u092e\u0949\u0921\u0932 \u0905\u092a\u0928\u0940 \u0939\u0932\u094d\u0915\u0940 \u0932\u0940\u0928\u093f\u092f\u0930 \u092a\u094d\u0930\u0915\u0943\u0924\u093f \u0915\u0947 \u0915\u093e\u0930\u0923 \u0906\u0938\u093e\u0928\u0940 \u0938\u0947 \u092c\u093f\u0928\u093e \u092e\u0947\u092e\u094b\u0930\u0940 \u090f\u0930\u0930 (OOM) \u0915\u0947 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0939\u094b\u0928\u0947 \u092e\u0947\u0902 \u0938\u0915\u094d\u0937\u092e \u0939\u0948\u0964\n\n---\n\u092f\u0939 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0906\u0935\u0927\u093f\u0915 \u091f\u093e\u0907\u092e \u0938\u0940\u0930\u0940\u091c\u093c \u0915\u0947 \u0932\u093f\u090f CycleNet \u0915\u0947 \u0938\u092b\u0932 \u0914\u0930 \u0928\u093f\u0937\u094d\u092a\u0915\u094d\u0937 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0939\u0947\u0924\u0941 \u0938\u092d\u0940 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0935 \u0924\u0915\u0928\u0940\u0915\u0940 \u092e\u093e\u0928\u0915\u094b\u0902 \u0915\u094b \u092a\u0942\u0930\u094d\u0923 \u0915\u0930\u0924\u093e \u0939\u0948\u0964", "uncertainties": [], "evidence": "\u0935\u0930\u094d\u0915\u0938\u094d\u092a\u0947\u0938 \u092e\u0947\u0902 `task.json` \u0909\u092a\u0932\u092c\u094d\u0927 \u0939\u0948 \u091c\u094b \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u092f\u0939 \u090f\u0915 'Design-only task' \u0939\u0948\u0964 \u092a\u0930\u094d\u092f\u093e\u0935\u0930\u0923 \u092e\u0947\u0902 Python 3.12 \u0909\u092a\u0932\u092c\u094d\u0927 \u0939\u0948 \u0914\u0930 \u0928\u094